import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent } from '@domg-wc/components/atom';
import {
    CrossValidationMixin,
    parseFormData,
    VlFormLabelComponent,
    VlFormMessageComponent,
    VlInputFieldComponent,
    VlSelectComponent,
} from '@domg-wc/components/form';

// Een eigen component per validator. CrossValidationMixin hervalideert het veld zodra een veld uit
// dependencySelectors een vl-change geeft; instance is het element zelf, instance.form het native formulier.
class VlInputFieldWithCrossValidatorComponent extends CrossValidationMixin(VlInputFieldComponent) {
    static formControlValidators = [
        ...VlInputFieldComponent.formControlValidators,
        {
            key: 'customError',
            message: `Bij de strikte procedure moet de code 'ABC-123' zijn.`,
            dependencySelectors: ['#procedure'],
            isValid(instance, value) {
                if (!value) return true;

                const form = instance.form;
                if (!form) return true;

                const procedure = form.querySelector('#procedure')?.value;
                return procedure !== 'strikt' || value === 'ABC-123';
            },
        },
    ];
}
customElements.define('vl-input-field-with-cross-validator', VlInputFieldWithCrossValidatorComponent);

registerWebComponents([VlFormLabelComponent, VlFormMessageComponent, VlSelectComponent, VlButtonComponent]);

document.querySelector('#procedure').options = [
    { label: 'Standaard', value: 'standaard' },
    { label: 'Strikt (vereist code "ABC-123")', value: 'strikt' },
];

// De ingediende form data komt onder het formulier, via parseFormData.
const form = document.querySelector('#form');
const output = document.querySelector('#form-data');
form.addEventListener('submit', (event) => {
    event.preventDefault();
    output.textContent = JSON.stringify(parseFormData(form), null, 2);
    output.hidden = false;
});
form.addEventListener('reset', () => {
    output.textContent = '';
    output.hidden = true;
});

