    static formControlValidators = [
        ...VlInputFieldComponent.formControlValidators,
        {
            key: 'customError',
            message: 'De e-mailadressen komen niet overeen.',
            dependencySelectors: ['#email'],
            isValid(instance, value) {
                if (!value) return true;

                const form = instance.form;
                if (!form) return true;

                const email = form.querySelector('#email')?.value;
                return value === email;
            },
        },
    ];
}
customElements.define('vl-input-field-with-match-validator', VlInputFieldWithMatchValidatorComponent);

registerWebComponents([VlFormLabelComponent, VlFormMessageComponent, VlInputFieldComponent, VlButtonComponent]);

