import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent } from '@domg-wc/components/atom';
import {
    CrossValidationMixin,
    VlFormLabelComponent,
    VlFormMessageComponent,
    VlInputFieldComponent,
    VlSelectComponent,
} from '@domg-wc/components/form';

// Het veld heeft geen required: de validator maakt het verplicht zodra de reden 'andere' is,
// en hervalideert het bij elke vl-change van #reden.
class VlInputFieldWithConditionalValidatorComponent extends CrossValidationMixin(VlInputFieldComponent) {
    static formControlValidators = [
        ...VlInputFieldComponent.formControlValidators,
        {
            key: 'customError',
            message: 'Gelieve de reden te verduidelijken.',
            dependencySelectors: ['#reden'],
            isValid(instance, value) {
                const form = instance.form;
                if (!form) return true;

                const reden = form.querySelector('#reden')?.value;
                if (reden !== 'andere') return true;

                return !!value;
            },
        },
    ];
}
customElements.define('vl-input-field-with-conditional-validator', VlInputFieldWithConditionalValidatorComponent);

registerWebComponents([VlFormLabelComponent, VlFormMessageComponent, VlSelectComponent, VlButtonComponent]);

const form = document.querySelector('#form');
const reden = document.querySelector('#reden');
const label = document.querySelector('vl-form-label[for="verduidelijking"]');

reden.options = [
    { label: 'Verlenging', value: 'verlenging' },
    { label: 'Andere', value: 'andere' },
];

// Bij de reden 'andere' markeert het label het veld als verplicht.
const updateLabel = (value) =>
    label.setAttribute('label', value === 'andere' ? 'Verduidelijking *' : 'Verduidelijking');
form.addEventListener('vl-change', () => updateLabel(reden.value));
form.addEventListener('reset', () => updateLabel(''));
form.addEventListener('submit', (event) => event.preventDefault());
